type FiringJob={slug:string;keyword:string;make:string;model:string;title:string;order:string;numbering:string;scope:string;detail:string;source:Source;sources?:Source[]};
const firingJobs:FiringJob[]=[
  {slug:"chevrolet/6-2-diesel/firing-order",keyword:"chevy 6.2 diesel firing order",make:"Chevrolet",model:"6.2L Detroit Diesel V8",title:"Chevy 6.2 Diesel Firing Order and Injection-Line Diagram",order:"1-8-7-2-6-5-4-3",numbering:"Driver/left bank is 1-3-5-7 and passenger/right bank is 2-4-6-8, front to rear, with cylinder 1 at the forward left position.",scope:"Covers GM 6.2L IDI diesel V8 engines used in light- and heavy-duty truck applications; it does not cover the modern 6.2L gasoline V8 or later Duramax diesels.",detail:"The mechanical order is only the first layer of an injection-line check. Keep the rigid lines in their original clamps, identify every DB2 pump outlet from the exact pump/application diagram, and do not bend lines into a visually convenient route.",source:gm62Training,sources:[gm62Training,S.gm]},
  {slug:"chevrolet/6-5-diesel/firing-order",keyword:"chevy 6.5 diesel firing order",make:"Chevrolet",model:"6.5L Detroit Diesel V8",title:"Chevy 6.5 Diesel Firing Order and Cylinder Numbering",order:"1-8-7-2-6-5-4-3",numbering:"Driver/left bank is 1-3-5-7 and passenger/right bank is 2-4-6-8, front to rear.",scope:"Covers GM 6.5L IDI diesel V8 mechanical-pump and electronic-pump applications after confirming the installed engine, pump and vehicle wiring.",detail:"DB2 mechanical and DS4 electronic pump systems share the engine's mechanical sequence but not its controls, timing method, optical-sensor diagnosis or harness layout. The military manual corroborates the base order; civilian model-year service data controls the exact diagnostic procedure.",source:gm65Military,sources:[gm65Military,S.gm]},
  {slug:"ford/6-9-idi/firing-order",keyword:"ford 6.9 idi firing order",make:"Ford",model:"1983–1987 6.9L IDI Diesel V8",title:"Ford 6.9 IDI Firing Order and Injection-Line Diagram",order:"1-2-7-3-4-5-6-8",numbering:"The passenger/right bank is 1-3-5-7 and the driver/left bank is 2-4-6-8, with both banks numbered from the front of the engine toward the transmission.",scope:"Covers the Ford/International 6.9L indirect-injection V8 used in 1983–1987-era F-Series and E-Series applications. It does not cover the later 7.3L IDI, the 7.3L Power Stroke or gasoline Ford V8 numbering diagrams.",detail:"The firing order identifies combustion sequence, not the physical path of the formed DB2 injection lines. Label every line, match each pump outlet to the exact service diagram and keep all vibration clamps in place; forcing a line into the nearest cylinder can crack it or create a dangerous high-pressure fuel leak.",source:ford69IdiWorkshop,sources:[ford69IdiWorkshop,S.ford]},
  {slug:"ford/7-3-idi/firing-order",keyword:"ford 7.3 idi firing order",make:"Ford",model:"7.3L IDI Diesel V8",title:"Ford 7.3 IDI Firing Order and Cylinder Diagram",order:"1-2-7-3-4-5-6-8",numbering:"Passenger/right bank is 1-3-5-7 and driver/left bank is 2-4-6-8, front to rear.",scope:"Covers naturally aspirated and factory-turbo 7.3L indirect-injection engines used in Ford trucks and vans; it does not cover the later direct-injection 7.3L Power Stroke.",detail:"The IDI and Power Stroke share nominal displacement and the base firing sequence, but not injectors, pump, high-pressure-oil system, wiring or diagnostic method. A DB2 pump and visible hard injector lines identify the IDI architecture; preserve their clamps and match the pump-outlet diagram before disturbing them.",source:ford73IdiWorkshop,sources:[ford73IdiWorkshop,S.ford]},
  {slug:"ford/7-3-power-stroke/firing-order",keyword:"ford 7.3 powerstroke firing order",make:"Ford",model:"7.3L Power Stroke V8",title:"Ford 7.3 Power Stroke Firing Order and Cylinder Numbering",order:"1-2-7-3-4-5-6-8",numbering:"Passenger/right bank is 1-3-5-7 and driver/left bank is 2-4-6-8, front to rear.",scope:"Covers Ford/Navistar 7.3L Power Stroke direct-injection HEUI engines from the 1994.5–2003 light-truck era after confirming the installed calibration and harness generation.",detail:"Cylinder identity, injector-driver electrical order, contribution-test display and firing-event position are related but not interchangeable references. The under-valve-cover harness and external connector arrangement changed during production, so model-year wiring must accompany the physical cylinder diagram.",source:ford73PsdFactory,sources:[ford73PsdFactory,ford73PsdSupplement]},
  {slug:"ford/6-0-power-stroke/firing-order",keyword:"ford 6.0 powerstroke firing order",make:"Ford",model:"6.0L Power Stroke V8",title:"Ford 6.0 Power Stroke Firing Order and Cylinder Diagram",order:"1-2-7-3-4-5-6-8",numbering:"Passenger/right bank is 1-3-5-7 and driver/left bank is 2-4-6-8, front to rear.",scope:"Covers the 6.0L Power Stroke/Navistar VT365 used in Ford applications, including the F-Series, Excursion and E-Series years that received this engine; it does not cover the older 7.3L or later 6.4L service systems.",detail:"Use the physical cylinder number when interpreting power-balance, injector-circuit, contribution and glow-plug faults. The 6.0L's FICM and HEUI high-pressure-oil system make connector identity and hydraulic diagnosis separate from the mechanical firing sequence.",source:ford60Tech,sources:[ford60Tech,S.ford]},
  {slug:"ford/6-4-power-stroke/firing-order",keyword:"ford 6.4 powerstroke firing order",make:"Ford",model:"6.4L Power Stroke V8",title:"Ford 6.4 Power Stroke Firing Order and Cylinder Numbering",order:"1-2-7-3-4-5-6-8",numbering:"Passenger/right bank is 1-3-5-7 and driver/left bank is 2-4-6-8, front to rear.",scope:"Covers the Ford/Navistar 6.4L Power Stroke used in 2008–2010 Super Duty applications with the production camshaft and cylinder numbering.",detail:"Although the sequence matches the 6.0L, the 6.4L uses high-pressure common-rail injection and piezoelectric injectors rather than HEUI. Depressurization, injector coding, fuel-tube replacement and contamination procedures therefore require 6.4L-specific service information.",source:ford64Tech,sources:[ford64Tech,S.ford]},
  {slug:"ram/5-9-cummins-12v/firing-order",keyword:"dodge 5.9 cummins 12v firing order",make:"Ram",model:"5.9L Cummins 12-Valve I6",title:"Dodge 5.9 Cummins 12V Firing Order and Cylinder Diagram",order:"1-5-3-6-2-4",numbering:"Cylinders 1 through 6 run from the front gear/radiator end toward the flywheel and transmission.",scope:"Covers the mechanically injected 5.9L Cummins 6BT 12-valve used in Dodge trucks; industrial and repower installations must be oriented from the engine's gear housing rather than the vehicle body.",detail:"The engine is a single-bank inline six, but injection-pump outlet routing is not established by drawing the shortest line to each cylinder. Match the exact Bosch VE or P7100 pump diagram, keep every formed line in its original support clamps, and identify the engine and pump before loosening a line.",source:cumminsFiring,sources:[cumminsFiring,cummins59,S.cummins]},
  {slug:"ram/5-9-cummins-24v/firing-order",keyword:"dodge 5.9 cummins 24v firing order",make:"Ram",model:"5.9L Cummins 24-Valve I6",title:"Dodge 5.9 Cummins 24V Firing Order and Cylinder Diagram",order:"1-5-3-6-2-4",numbering:"Cylinders 1-2-3-4-5-6 run from the front gear housing toward the flywheel and transmission.",scope:"Covers Dodge/Ram 5.9L Cummins ISB 24-valve truck engines, while separating VP44-era and high-pressure-common-rail versions for fuel-system work.",detail:"The mechanical combustion order stays 1-5-3-6-2-4 across these 24-valve versions, but VP44 and common-rail systems do not share pump, line, injector or electrical procedures. Retrieve serial-number-specific Cummins information before opening the fuel system.",source:cumminsFiring,sources:[cumminsFiring,cummins59,S.cummins]},
];
function firingPage(j:FiringJob):SpecRecord{return firingGuide({slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Firing Order",title:j.title,
  metaDescription:`${j.title}: ${j.order}, diesel bank numbering, injection-system distinctions and routing cautions.`,answer:`The ${j.model} firing order is ${j.order}. ${j.numbering}`,scope:j.scope,detail:j.detail,
  values:[{label:"Firing order",value:j.order,note:"Verify exact engine"},{label:"Cylinder numbering",value:j.numbering,note:"Orient from engine front"}],sources:j.sources??[j.source],identity:j.model,distinctions:[j.scope,j.detail],featureImage:engineImage,featureOverlay:true});}

type HeadJob={slug:string;keyword:string;make:string;model:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source};
const headJobs:HeadJob[]=[
  {slug:"mitsubishi/4g63/head-bolt-torque",keyword:"mitsubishi 4g63 head bolt torque specs",make:"Mitsubishi",model:"4G63 Turbo Inline-Four",title:"Mitsubishi 4G63 Head Bolt Torque Specs and Sequence",answer:"For the 4G63 turbo application covered by the linked Mitsubishi overhaul manual, tighten the oiled factory bolts to 78 ± 2 N·m, loosen them completely, tighten to 20 ± 2 N·m, then turn every bolt 90° and another 90° in sequence.",scope:"This numerical procedure covers the factory-bolt 4G63 turbo revision documented in the linked manual. Earlier 6-bolt engines, naturally aspirated variants, Evolution revisions and aftermarket studs must be matched to their own manual or fastener chart.",detail:"Inspect bolt length before reuse, oil the threads and washer faces as specified, and use paint marks for both angle passes. If an angle is exceeded, the manual directs loosening the bolt completely and restarting the procedure rather than backing it off to the mark.",values:[{label:"Stage 1",value:"78 ± 2 N·m",note:"57.5 ± 1.5 lb-ft; exact sequence"},{label:"Stage 2",value:"Loosen completely",note:"All bolts"},{label:"Stage 3",value:"20 ± 2 N·m",note:"14.8 ± 1.5 lb-ft"},{label:"Stages 4 and 5",value:"90° + 90°",note:"Paint-mark each bolt"},{label:"Fastener condition",value:"Inspect length; oil threads/washer",note:"Use the manual's limit"}],source:mitsubishi4g63Head},
  {slug:"ford/7-3-power-stroke/head-bolt-torque",keyword:"ford 7.3 powerstroke head bolt torque specs",make:"Ford",model:"2002 F-350 7.3L Power Stroke V8",title:"Ford 7.3 Power Stroke Head Bolt Torque Specs and Sequence",answer:"For the covered 2002 F-350 7.3L Power Stroke, lightly oil the factory head-bolt threads and flanges, then tighten in the specified sequences to 65 lb-ft, 85 lb-ft and finally 95 lb-ft.",scope:"The three-stage chart is anchored to the 2002 Super Duty 7.3L direct-injection Power Stroke. The earlier 7.3L IDI, International medium-duty variants, nonstandard gaskets and aftermarket studs require their exact instructions.",detail:"Ford warns against excessive oil and against anti-seize, grease or any lubricant other than clean engine oil because thread friction changes the true clamp load. The final 95-lb-ft pass uses the manual's second sequence rather than simply repeating an invented center-out order.",values:[{label:"Stage 1",value:"65 lb-ft",note:"88 N·m; first Ford sequence"},{label:"Stage 2",value:"85 lb-ft",note:"115 N·m; repeat first sequence"},{label:"Stage 3",value:"95 lb-ft",note:"129 N·m; use second sequence"},{label:"Thread preparation",value:"Light clean engine oil",note:"No anti-seize or grease"},{label:"Aftermarket studs",value:"Kit-specific procedure",note:"Specified lubricant controls"}],source:ford73PsdHead2002},
  {slug:"ford/6-0-power-stroke/head-bolt-torque",keyword:"ford 6.0 powerstroke head bolt torque specs",make:"Ford",model:"2004 F-350 6.0L Power Stroke V8",title:"Ford 6.0 Power Stroke Head Bolt Torque Specs and Sequence",answer:"For the covered 2004 F-350 6.0L Power Stroke, use new head bolts: tighten main bolts 1–10 to 65 lb-ft; take odd-numbered main bolts 1, 3, 5, 7 and 9 to 85 lb-ft; then turn all main bolts 90° three times. Tighten small bolts 11–15 to 18 and then 23 lb-ft.",scope:"The exact stages apply to the documented 2004 Super Duty 6.0L factory-bolt procedure. Later service revisions, E-Series packaging, machined assemblies, nonstandard gaskets and stud conversions must use their matching instructions.",detail:"The 85-lb-ft stage does not apply to every main bolt, and the five small bolts do not receive the 90° turns. Keep both fastener groups labeled and record every completed angle pass; aftermarket studs replace this factory torque-to-yield procedure completely.",values:[{label:"Main bolts 1–10 — stage 1",value:"65 lb-ft",note:"88 N·m; new bolts"},{label:"Odd main bolts 1,3,5,7,9",value:"85 lb-ft",note:"115 N·m; position-specific stage"},{label:"All main bolts 1–10",value:"90° + 90° + 90°",note:"Three clockwise sequence passes"},{label:"Small bolts 11–15",value:"18 then 23 lb-ft",note:"24 then 31 N·m; no angle turn"},{label:"Stud conversion",value:"Stud-maker chart",note:"Do not mix procedures"}],source:ford60PsdHead2004},
  {slug:"ram/5-9-cummins/head-bolt-torque",keyword:"dodge 5.9 cummins head bolt torque specs",make:"Ram",model:"2002 Ram 3500 5.9L Cummins 24-Valve I6",title:"Dodge 5.9 Cummins Head Bolt Torque Specs and Sequence",answer:"For the covered 2002 Ram 3500 5.9L Cummins 24-valve, tighten the head bolts in sequence to 59 lb-ft and then 77 lb-ft, recheck every bolt at 77 lb-ft, and turn each bolt an additional 90°.",scope:"The chart is anchored to the 2002 VIN 6 24-valve Cummins factory-bolt procedure. Earlier 12-valve engines, 2003-and-later common-rail revisions, engine-serial-number changes and aftermarket studs require separate Cummins or fastener data.",detail:"Inspect every bolt for damaged threads, corrosion, pitting and necking. The covered procedure permits reuse only when the bolt passes inspection and its free length stays below the 132.1 mm (5.200 in) discard limit supplied with the replacement gasket gauge.",values:[{label:"Stage 1",value:"59 lb-ft",note:"80 N·m; exact sequence"},{label:"Stage 2",value:"77 lb-ft",note:"105 N·m; repeat sequence"},{label:"Verification",value:"Recheck 77 lb-ft",note:"Confirm every bolt before angle"},{label:"Final turn",value:"90°",note:"Additional 1/4 turn"},{label:"Maximum reusable free length",value:"Below 132.1 mm",note:"5.200 in; also inspect condition"}],source:cummins59Head2002},
  {slug:"gm/6-6-duramax/head-bolt-torque",keyword:"gm 6.6 duramax head bolt torque specs",make:"GMC",model:"2002 Silverado/Sierra 6.6L LB7 Duramax V8",title:"GM 6.6 Duramax LB7 Head Bolt Torque Specs",answer:"For the covered 2002 LB7 Duramax, install new M12 head bolts and tighten them in sequence to 37 lb-ft, then 59 lb-ft, followed by two separate 60° turns. Reused M8 head bolts tighten to 18 lb-ft.",scope:"This procedure is anchored to the 2002 VIN 1 LB7 6.6L Duramax service information updated by GM bulletin data. LLY, LBZ, LMM, LML and L5P engines, replacement stud kits and later service revisions require their exact RPO procedure.",detail:"The new-bolt rule applies to the M12 main group; the cited procedure explicitly allows reuse of the M8 group. Do not apply the two 60° turns to the M8 bolts, and use the factory sequence plus an angle meter for both M12 rotation stages.",values:[{label:"M12 stage 1",value:"37 lb-ft",note:"50 N·m; install new bolts"},{label:"M12 stage 2",value:"59 lb-ft",note:"80 N·m"},{label:"M12 angle stages",value:"60° + 60°",note:"Two separate passes with angle tool"},{label:"M8 head bolts",value:"18 lb-ft",note:"25 N·m; reusable in cited procedure"},{label:"Other Duramax RPO",value:"Separate procedure",note:"Do not transfer LB7 stages"}],source:duramaxLb7Head2002},
];
const researchedHeadEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "ford/7-3-power-stroke/head-bolt-torque":{sections:[
    {heading:"The 2002 7.3L three-stage procedure",paragraphs:["Ford's covered installation starts with all head bolts lightly coated at the threads and flanges with clean engine oil. Tighten the first illustrated sequence to 65 lb-ft, repeat that sequence at 85 lb-ft, then use the manual's second sequence for the 95-lb-ft final pass.","The sequence change at the final stage is easy to lose in a simplified chart. Use the factory numbered drawing for the actual bolt positions; the interactive site diagram is an orientation aid, not a replacement for that drawing."]},
    {heading:"Lubricant and bolt-hole control",paragraphs:["Ford cautions that too much oil can damage threads and compromise sealing. It also prohibits anti-seize, grease and other lubricants because the published wrench values are calibrated to a light film of clean engine oil.","Clean the holes by the approved method and confirm that they contain no coolant, oil or debris. A bolt that hydraulically bottoms can display torque before the head is clamped and can damage the block."]},
    {heading:"Power Stroke versus IDI and stud builds",paragraphs:["The 1994.5–2003 direct-injection HEUI Power Stroke is not the earlier 7.3L IDI even though both share a nominal displacement. Head, bolt and service procedures must be selected by engine architecture and model year.","An aftermarket stud kit supplies its own lubricant, tightening stages and often a different final value. Do not run the Ford 65/85/95-lb-ft bolt chart and then add the stud-maker torque on top."]},
  ],faqs:[{q:"What are the 2002 Ford 7.3 Power Stroke head-bolt stages?",a:"Use 65 lb-ft and 85 lb-ft in Ford's first sequence, then 95 lb-ft in the second sequence."},{q:"What lubricant does Ford specify on the 7.3L head bolts?",a:"Apply only a light coating of clean engine oil to the threads and flanges; the covered procedure warns against excess oil, anti-seize and grease."},{q:"Does this chart cover the 7.3L IDI diesel?",a:"No. It is scoped to the direct-injection 2002 Power Stroke application."},{q:"Do 7.3 Power Stroke studs use 65/85/95 lb-ft?",a:"Not automatically. Follow the stud manufacturer's stages and specified lubricant for the exact kit."}]},
  "ford/6-0-power-stroke/head-bolt-torque":{sections:[
    {heading:"Separate the ten main bolts from five small bolts",paragraphs:["Ford requires new head bolts in the covered 2004 procedure. Main bolts 1–10 first receive 65 lb-ft, but only odd positions 1, 3, 5, 7 and 9 receive the intermediate 85-lb-ft step. All ten main bolts then receive three separate 90° turns in sequence.","Small bolts 11–15 are a separate group. They tighten to 18 lb-ft and then 23 lb-ft and do not receive any of the three angle turns."]},
    {heading:"Recording three full angle passes",paragraphs:["Use a stable angle gauge and mark each main bolt after every completed pass. Finish all ten positions through one 90° sequence before starting the second, and complete the second before the third; one estimated 270° movement is not the published workflow.","If the wrench movement becomes abnormal or a bolt does not seat normally, stop. Do not reverse a finished angle to correct a paint mark without following the service procedure for a restarted installation."]},
    {heading:"Why stud-conversion instructions replace this chart",paragraphs:["The factory procedure is built around new torque-to-yield bolts. A stud kit changes the fastener, thread friction, washer system and clamp calculation, so it uses the kit maker's lubricant and torque stages instead of Ford's 90° passes.","Cylinder-head and block flatness, surface finish and gasket choice also remain critical. More clamp load cannot compensate for an improperly prepared sealing surface."]},
  ],faqs:[{q:"What are the 2004 Ford 6.0 Power Stroke main head-bolt stages?",a:"Tighten bolts 1–10 to 65 lb-ft, bolts 1/3/5/7/9 to 85 lb-ft, then turn all ten main bolts 90° three separate times."},{q:"What torque applies to 6.0L small head bolts 11–15?",a:"The covered procedure uses 18 lb-ft followed by 23 lb-ft, with no angle turn for that small-bolt group."},{q:"Can the covered 6.0 Power Stroke head bolts be reused?",a:"No. Ford's cited specification explicitly requires new cylinder-head bolts."},{q:"Do 6.0 Power Stroke studs use the factory angle stages?",a:"No. Use the stud maker's torque, lubricant and sequence instead of mixing the two systems."}]},
  "ram/5-9-cummins/head-bolt-torque":{sections:[
    {heading:"The 2002 Cummins 24-valve sequence stages",paragraphs:["Run the complete numbered pattern at 59 lb-ft, repeat it at 77 lb-ft, and verify every bolt remains at 77 lb-ft. Only after that verification does each position receive the additional quarter-turn, or 90°.","A long inline-six head benefits from disciplined full-pattern passes. Do not finish one end of the head at 90° while the opposite end remains at the first torque stage."]},
    {heading:"Factory bolt inspection and free length",paragraphs:["Inspect threads and shanks for damage, corrosion, pitting and visible necking. The replacement-gasket gauge used by the covered procedure establishes a maximum free length of 132.1 mm (5.200 in); a bolt that reaches the gauge's discard point must be replaced.","Passing the length gauge does not excuse surface damage. Any bolt with compromised threads or reduced shank diameter is unsuitable even if its overall length appears acceptable."]},
    {heading:"12-valve, 24-valve and common-rail boundaries",paragraphs:["This page is tied to the 2002 VP44-era 24-valve truck engine. Earlier 12-valve 6BT engines and 2003-and-later common-rail ISB revisions must be retrieved by engine serial number rather than merged into one 5.9L chart.","Stud kits also replace the factory-bolt stages. Use the fastener maker's lubricant and instructions for the exact head, gasket and kit."]},
  ],faqs:[{q:"What are the 2002 Dodge 5.9 Cummins head-bolt stages?",a:"Use 59 lb-ft, then 77 lb-ft, verify every bolt at 77 lb-ft, and finally turn all bolts an additional 90° in sequence."},{q:"What is the 5.9 Cummins head-bolt free-length limit?",a:"The covered procedure uses a 132.1 mm (5.200 in) maximum and also requires inspection for damage, corrosion, pitting and necking."},{q:"Does this chart cover a 12-valve Cummins?",a:"No. It is anchored to a 2002 24-valve application; obtain serial-number-specific information for other versions."},{q:"Can aftermarket Cummins studs use this 90° finish?",a:"No. Follow the stud manufacturer's torque stages and lubricant specification."}]},
  "gm/6-6-duramax/head-bolt-torque":{sections:[
    {heading:"The 2002 LB7 M12 and M8 bolt groups",paragraphs:["Install new M12 main bolts and take them through 37 lb-ft, 59 lb-ft, then two distinct 60° sequence passes. The smaller M8 bolts form a separate group and finish at 18 lb-ft without an angle stage.","The cited GM procedure permits reuse of the M8 bolts while explicitly requiring new M12 bolts. Keep the groups separated during cleaning and parts ordering so the reuse rule and final stages cannot be crossed."]},
    {heading:"Applying two measured 60° turns",paragraphs:["Use the factory LB7 bolt map and an angle meter. Complete the first 60° turn at every M12 position before beginning the second pass; paint marks can help verify completion but should not replace the measuring tool.","Do not combine the two passes into one 120° pull. Separate passes distribute the final clamp increase through the entire head in the sequence GM intended."]},
    {heading:"Why later Duramax RPOs need new research",paragraphs:["LB7, LLY, LBZ, LMM, LML and L5P identify different 6.6L revisions. This page's 2002 VIN 1 data must not be transferred merely because a later valve cover still says Duramax.","Aftermarket studs likewise use their own washers, lubricant and torque chart. Surface preparation, gasket specification and any GM bulletin supersession must match the engine RPO being assembled."]},
  ],faqs:[{q:"What are the 2002 LB7 Duramax M12 head-bolt stages?",a:"Use new M12 bolts and tighten them to 37 lb-ft, then 59 lb-ft, followed by two separate 60° turns in sequence."},{q:"What torque applies to the LB7 M8 head bolts?",a:"The covered procedure tightens the reusable M8 bolts to 18 lb-ft (25 N·m) without an angle stage."},{q:"Can the LB7 M12 head bolts be reused?",a:"No. The cited GM service data directs installation of new M12 cylinder-head bolts."},{q:"Does this LB7 chart cover LLY, LBZ, LMM, LML or L5P engines?",a:"No. Each later Duramax RPO requires its exact service procedure and current bulletin information."}]},
};
function headPage(j:HeadJob):SpecRecord{const record:SpecRecord={slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Torque Specs",title:j.title,
  metaDescription:`${j.title} with application boundaries, fastener distinctions, staged sequence guidance and official service lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:[j.source],reviewed,featureImage:engineImage,featureOverlay:true,
  diagram:{type:"head",title:`Interactive ${j.model} head sequence aid`,caption:"Orientation aid only. Use the exact manufacturer bolt map and stages for assembly.",points:["1","5","9","7","3","4","8","10","6","2"]},intro:[j.answer,j.scope],
  steps:["Identify the engine serial/RPO, model year, cylinder head, gasket and fastener kit.","Verify flatness, surface finish, threads and empty bolt holes.","Complete each torque, loosen and angle stage in the exact numbered order."],sections:[{heading:`Application boundaries for ${j.model}`,paragraphs:[j.scope,j.detail]}],
  faqs:dieselServiceFaqs[j.slug]??[{q:`What are the ${j.keyword}?`,a:j.answer},{q:"Can factory head bolts be reused?",a:"Only when the exact service procedure permits it and the bolts pass every inspection limit."},{q:"Can a stud kit use the factory procedure?",a:"No. Use the fastener maker's torque, lubricant and sequence for the exact kit."}]};const editorial=researchedHeadEditorial[j.slug];if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;record.intro=[record.answer,record.scope,record.detail];}return record;}

type TorqueJob={slug:string;keyword:string;make:string;model:string;title:string;answer:string;scope:string;detail:string;values:SpecValue[];source:Source;sources?:Source[];diagram?:"intake"|"timing"|"main"};
const torqueJobs:TorqueJob[]=[
  {slug:"chevrolet/350/starter-bolt-torque",keyword:"chevy 350 starter bolt torque spec",make:"Chevrolet",model:"350 Small-Block V8",title:"Chevy 350 Starter Bolt Torque Specs and Fit Checks",answer:"Chevrolet Performance does not publish one universal Chevy 350 starter-bolt number: its 350 HO Turn Key guide specifies 30 lb-ft (40 N·m), while the 350 HO Deluxe and 350/265 HP long-block guides specify 35 lb-ft (48 N·m). Use the value for the installed starter and engine package.",scope:"The 30- and 35-lb-ft figures are package-specific Chevrolet Performance specifications, not permission to average them. Production engines, replacement mini-starters, different bolt diameters and aftermarket nose housings can carry different instructions.",detail:"Use correct shouldered or knurled starter bolts of the prescribed length, install any factory brace, and verify pinion-to-ring-gear engagement before adding shims. A starter that shifts or sits crooked can damage the nose, bolt holes and ring gear even when a torque wrench reaches the nominal number.",values:[{label:"350 HO Turn Key supplied starter",value:"30 lb-ft",note:"40 N·m; package guide"},{label:"350 HO Deluxe / 350-265 long block",value:"35 lb-ft",note:"48 N·m; package guide"},{label:"Aftermarket starter",value:"Manufacturer instructions",note:"Match bolt and nose housing"}],source:chevy350HoTurnKey,sources:[chevy350HoTurnKey,chevy350HoDeluxe,chevy350_265],diagram:"main"},
  {slug:"chevrolet/350/exhaust-manifold-torque",keyword:"chevy 350 exhaust manifold torque spec",make:"Chevrolet",model:"1996 C1500 5.7L Vortec V8",title:"1996 Chevy 350 Exhaust Manifold Bolt Torque",answer:"For the covered 1996 Chevrolet C1500 5.7L Vortec, tighten the two center exhaust-manifold bolts to 26 lb-ft (35 N·m) and the remaining manifold bolts to 20 lb-ft (27 N·m).",scope:"This split specification applies to the documented production 1996 VIN R truck 5.7L cast manifolds and iron Vortec heads. Earlier Gen I heads, different model years, tube headers, aluminum heads and aftermarket fasteners require their own values.",detail:"Identify the center pair before tightening and bring the casting down progressively from the middle toward the ends. Inspect the manifold for cracks and flange warpage and repair damaged threads; extra torque on the outer bolts will not compensate for a bowed flange or failed gasket.",values:[{label:"Two center manifold bolts",value:"26 lb-ft",note:"35 N·m; special center positions"},{label:"All remaining manifold bolts",value:"20 lb-ft",note:"27 N·m"},{label:"Tightening direction",value:"Center outward",note:"Seat the long casting progressively"},{label:"Headers or aluminum heads",value:"Component instructions",note:"Do not transfer the truck cast-manifold chart"}],source:chevy350Exhaust1996},
  {slug:"chevrolet/350/oil-pan-bolt-torque",keyword:"chevy 350 oil pan bolt torque spec",make:"Chevrolet",model:"350 Small-Block V8",title:"Chevy 350 Oil Pan Bolt Torque Specs by Location",answer:"For the Chevrolet Performance 350 HO Deluxe, tighten the oil-pan side-rail bolts to 97 in-lb (11 N·m) and the corner bolts to 15 lb-ft (20 N·m). The drain plug is also listed at 15 lb-ft (20 N·m).",scope:"These exact values apply to the oil pan and hardware arrangement supplied or specified for the cited 350 HO Deluxe package. Earlier two-piece seals, aftermarket cast pans, one-piece gasket kits and mixed-size production hardware may use different location groups.",detail:"Separate the small side-rail bolts from the larger corner fasteners before starting. Flatten pulled bolt holes on a stamped pan, place sealant only where the gasket instructions call for it, start every bolt by hand, and tighten in gradual alternating passes. More torque will bow the flange and worsen a leak.",values:[{label:"Side-rail bolts",value:"97 in-lb",note:"11 N·m; 350 HO Deluxe"},{label:"Corner bolts",value:"15 lb-ft",note:"20 N·m; 350 HO Deluxe"},{label:"Oil-pan drain plug",value:"15 lb-ft",note:"20 N·m; separate joint"}],source:chevy350HoDeluxe,diagram:"main"},
  {slug:"chevrolet/350/water-pump-bolt-torque",keyword:"chevy 350 water pump bolt torque spec",make:"Chevrolet",model:"350 Small-Block V8",title:"Chevy 350 Water Pump Bolt Torque Specs",answer:"Chevrolet Performance specifies 30 lb-ft (40 N·m) for the water-pump bolts in its 350/265 HP long-block guide.",scope:"The 30-lb-ft value is a manufacturer specification for the covered Gen I small-block crate-engine arrangement. Accessory brackets captured under a bolt, aftermarket pumps, aluminum components and nonstandard fasteners still require their own instructions.",detail:"Keep each bolt in its original position because lengths can differ. Clean the block and pump faces, confirm whether the exact bolt hole or pump instructions require thread sealant, start all bolts by hand and tighten evenly so the pump does not cock against the gasket. Recheck for leaks after the first complete heat cycle without automatically retorquing.",values:[{label:"Water-pump bolts",value:"30 lb-ft",note:"40 N·m; Chevrolet Performance 350/265"},{label:"Aftermarket pump or bracket stack",value:"Component instructions",note:"Verify bolt length and sealant"}],source:chevy350_265,diagram:"timing"},
  {slug:"chevrolet/350/timing-cover-bolt-torque",keyword:"chevy 350 timing cover bolt torque spec",make:"Chevrolet",model:"350 Small-Block V8",title:"Chevy 350 Timing Cover Bolt Torque Specs",answer:"Chevrolet Performance specifies 97 in-lb (11 N·m) for the front-cover bolts on the 350 HO Deluxe.",scope:"This is an exact package value for the cited Gen I 350 HO Deluxe front cover. Cast aftermarket covers, reinforcement plates, different washers and accessory brackets can change the fastener stack and required torque.",detail:"Fit the cover loosely before the oil-pan corner seals are compressed, center it to the crank seal as the installation procedure requires, and tighten the small bolts evenly. The joint seals through correct alignment and gasket compression; overtightening can dish a stamped flange, squeeze out the seal or create a new leak path.",values:[{label:"Front/timing-cover bolts",value:"97 in-lb",note:"11 N·m; 350 HO Deluxe"},{label:"Cast aftermarket cover",value:"Manufacturer instructions",note:"Material and hardware may differ"}],source:chevy350HoDeluxe,diagram:"timing"},
  {slug:"ford/302/exhaust-manifold-torque",keyword:"ford 302 exhaust manifold torque spec",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"1996 Ford 302 Exhaust Manifold Torque Specs",answer:"For the covered 1996 Ford F-150 5.0L/302, tighten the exhaust-manifold-to-cylinder-head fasteners to 18–24 lb-ft (25–32 N·m).",scope:"The range applies to the production cast-manifold joint on the documented 1996 truck 5.0L. Earlier carbureted 302s, Mustang applications, aluminum heads, tube headers and aftermarket fasteners require their matching instructions.",detail:"Do not confuse the manifold-to-head fasteners with the exhaust-manifold-to-catalytic-converter nuts, which the covered service information lists separately at 25–34 lb-ft. Inspect flange flatness and use the exact gasket and locking-hardware procedure for the installed parts.",values:[{label:"Exhaust manifold to cylinder head",value:"18–24 lb-ft",note:"25–32 N·m; covered 1996 5.0L"},{label:"Manifold to catalytic converter",value:"25–34 lb-ft",note:"34–46 N·m; separate joint"},{label:"Tube header / aluminum head",value:"Component-maker procedure",note:"Stock cast-manifold range may not apply"}],source:ford302Truck1996Torque},
  {slug:"ford/302/oil-pan-bolt-torque",keyword:"ford 302 oil pan bolt torque spec",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"1996 Ford 302 Oil Pan Bolt Torque Specs",answer:"For the covered 1996 Ford F-150 5.0L/302 stamped oil pan, tighten the oil-pan bolts to 9–11 lb-ft (12–15 N·m).",scope:"This range is anchored to the production 1996 truck 5.0L oil-pan joint. Earlier multi-piece gasket systems, replacement one-piece gaskets, main-cap studs with pan rails and aftermarket cast-aluminum pans require their own instructions.",detail:"Straighten distorted stamped rails before assembly, apply sealant only at the specified cover/block and rear-cap joints, and tighten evenly in several passes. More torque will dish the rail, split the gasket or squeeze sealant out rather than repair a leak.",values:[{label:"Oil-pan bolts",value:"9–11 lb-ft",note:"12–15 N·m; covered stamped pan"},{label:"Pan rail condition",value:"Flat and undimpled",note:"Repair distortion before assembly"},{label:"Cast aftermarket pan / special gasket",value:"Manufacturer procedure",note:"Hardware and clamp load can differ"}],source:ford302Truck1996Torque,diagram:"main"},
  {slug:"ford/302/flywheel-bolt-torque",keyword:"ford 302 flywheel torque spec",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"1996 Ford 302 Flywheel Bolt Torque Specs",answer:"For the covered 1996 Ford F-150 5.0L/302, tighten the production flywheel-to-crankshaft bolts to 75–85 lb-ft (102–115 N·m).",scope:"The range is tied to the documented production crankshaft and flywheel joint. Automatic-transmission flexplates, aftermarket flywheels, performance bolt kits, different rear-main-seal generations and engine swaps require their exact parts documentation.",detail:"Confirm the correct 50-ounce-inch imbalance for the late production 5.0L combination, clean the crank flange and flywheel mating faces, install the specified bolts and thread treatment, and tighten progressively in a crisscross pattern. Runout and balance cannot be corrected by extra torque.",values:[{label:"Flywheel to crankshaft",value:"75–85 lb-ft",note:"102–115 N·m; covered 1996 5.0L"},{label:"Balance compatibility",value:"Match engine and flywheel",note:"Late 5.0L commonly uses 50 oz-in imbalance"},{label:"Aftermarket flywheel or bolts",value:"Manufacturer chart",note:"Thread lubricant changes clamp load"}],source:ford302Truck1996Torque,diagram:"main"},
  {slug:"ford/302/harmonic-balancer-bolt-torque",keyword:"ford 302 harmonic balancer torque spec",make:"Ford",model:"1996 F-150 5.0L/302 V8",title:"1996 Ford 302 Harmonic Balancer Bolt Torque",answer:"For the covered 1996 Ford F-150 5.0L/302, tighten the crankshaft-damper retaining bolt to 70–90 lb-ft (95–122 N·m).",scope:"This range applies to the documented production 5.0L crankshaft, damper and retaining bolt. Earlier 289/302 combinations, replacement crankshafts, aftermarket dampers and non-original bolt or washer kits require their corresponding instructions.",detail:"Inspect the key, keyway, crank snout, damper hub and elastomer before assembly. Use a dedicated damper installer to seat the hub; do not hammer the damper or use the retaining bolt to pull an unseated hub the full distance onto the crankshaft.",values:[{label:"Crankshaft damper bolt",value:"70–90 lb-ft",note:"95–122 N·m; covered 1996 5.0L"},{label:"Damper installation",value:"Dedicated installer",note:"Do not hammer or draw on with bolt"},{label:"Aftermarket damper or bolt",value:"Component-maker procedure",note:"Verify washer and thread treatment"}],source:ford302Truck1996Torque,diagram:"timing"},
  {slug:"chevrolet/5-3/exhaust-manifold-torque",keyword:"chevy 5.3 exhaust manifold torque spec",make:"Chevrolet",model:"2005 Silverado 1500 5.3L Gen III V8",title:"2005 Chevy 5.3 Exhaust Manifold Torque Specs and Sequence",answer:"For the covered 2005 Silverado 1500 5.3L Gen III V8, tighten the exhaust-manifold bolts center-out to 11 lb-ft (15 N·m), then repeat the sequence to 18 lb-ft (25 N·m). Tighten the separate manifold-to-pipe nuts to 37 lb-ft (50 N·m).",scope:"These values apply to the factory cast exhaust manifolds on the documented Gen III truck 5.3L installation. Later Gen IV or Gen V engines, headers, repaired cylinder-head threads and aftermarket hardware require their exact instructions.",detail:"Install a new gasket, clean the cylinder-head bolt-hole threads and apply the specified threadlocker as a 5-mm band while leaving the first three bolt threads bare. Begin with the center pair, alternate side to side and work outward; inspect broken rear bolts and flange warpage rather than trying to stop a leak with extra torque.",values:[{label:"Manifold bolts — first pass",value:"11 lb-ft",note:"15 N·m; center-out sequence"},{label:"Manifold bolts — final pass",value:"18 lb-ft",note:"25 N·m; repeat center-out"},{label:"Manifold-to-pipe nuts",value:"37 lb-ft",note:"50 N·m; separate flange joint"},{label:"Heat-shield bolts",value:"80 lb-in",note:"9 N·m; do not read as lb-ft"}],source:chevy53Exhaust2005},
  {slug:"chevrolet/5-3/flywheel-flexplate-torque",keyword:"chevy 5.3 flywheel torque spec",make:"Chevrolet",model:"2005 Silverado 1500 5.3L Gen III V8",title:"2005 Chevy 5.3 Flywheel and Flexplate Bolt Torque",answer:"For the covered 2005 Silverado 1500 5.3L Gen III crank-to-flywheel/flexplate joint, tighten in sequence to 15 lb-ft (20 N·m), then 37 lb-ft (50 N·m), and finally 74 lb-ft (100 N·m). Torque-converter-to-flexplate bolts are a separate joint at 46 lb-ft (63 N·m).",scope:"The staged crank-fastener procedure is anchored to the documented 2005 5.3L application. Confirm the transmission, flexplate or flywheel part number, spacer requirement, bolt length and balance before using it on a swap, manual conversion or aftermarket rotating assembly.",detail:"Clean the crank flange and mating faces, apply the specified GM threadlocker and start all fasteners by hand. The service procedure notes that the flywheel lacks a locating pin and is drawn evenly to the flange during the three passes; do not substitute the 46-lb-ft torque-converter value for the crank bolts.",values:[{label:"Crank bolts — pass 1",value:"15 lb-ft",note:"20 N·m; specified sequence"},{label:"Crank bolts — pass 2",value:"37 lb-ft",note:"50 N·m; keep plate seated evenly"},{label:"Crank bolts — final",value:"74 lb-ft",note:"100 N·m"},{label:"Torque converter to flexplate",value:"46 lb-ft",note:"63 N·m; separate fastener group"}],source:chevy53Flywheel2005,diagram:"main"},
  {slug:"chevrolet/5-3/harmonic-balancer-torque",keyword:"chevy 5.3 harmonic balancer torque spec",make:"Chevrolet",model:"2005 Silverado 1500 5.3L Gen III V8",title:"2005 Chevy 5.3 Harmonic Balancer Bolt Torque Procedure",answer:"On the covered 2005 Silverado 1500 5.3L, use the old crank bolt only to seat the balancer at 240 lb-ft (330 N·m), then remove it. Install a new final bolt, tighten it to 37 lb-ft (50 N·m), and turn it an additional 140 degrees.",scope:"This two-bolt procedure applies to the documented Gen III 5.3L production damper and crankshaft. Gen V engines, aftermarket dampers, supercharger hubs, ARP bolts and altered crank noses use the component maker's procedure.",detail:"First install the balancer with the approved installer, then use the old bolt for the seating operation. After the 240-lb-ft step, verify that the crank nose sits 0.094–0.176 in (2.4–4.48 mm) inside the balancer bore, discard the old bolt and complete the final clamp with a new bolt; 240 lb-ft is not the final new-bolt torque.",values:[{label:"Used bolt — seating only",value:"240 lb-ft",note:"330 N·m; remove after seating"},{label:"Required seating depth",value:"0.094–0.176 in",note:"2.4–4.48 mm crank recess"},{label:"New final bolt — initial",value:"37 lb-ft",note:"50 N·m"},{label:"New final bolt — angle",value:"+140°",note:"Use an angle gauge"}],source:chevy53Balancer2005,diagram:"timing"},
  {slug:"chevrolet/5-3/oil-pan-bolt-torque",keyword:"chevy 5.3 oil pan bolt torque spec",make:"Chevrolet",model:"2005 Silverado 1500 5.3L Gen III V8",title:"2005 Chevy 5.3 Oil Pan Bolt Torque by Fastener Group",answer:"For the covered 2005 Silverado 1500 5.3L, tighten the oil-pan and pan-to-front-cover bolts to 18 lb-ft (25 N·m). The pan-to-rear-cover bolts use 106 lb-in (12 N·m), while the bellhousing/converter-cover group uses 37 lb-ft (50 N·m).",scope:"These grouped values apply to the documented Gen III truck oil pan and cover arrangement. Two-wheel-drive versus four-wheel-drive pan shape, later engine generations, replacement cast pans and transmission configurations must be matched before transferring the chart.",detail:"Install a new gasket, align the oil-gallery openings and place the specified 5-mm sealant bead only at the block-to-cover joint tabs. Snug the pan without overtightening, align its rear face and cover joints, then apply the correct unit to each bolt group; confusing 106 lb-in with lb-ft will damage the joint.",values:[{label:"Pan and pan-to-front-cover bolts",value:"18 lb-ft",note:"25 N·m"},{label:"Pan-to-rear-cover bolts",value:"106 lb-in",note:"12 N·m; inch-pounds"},{label:"Bellhousing/converter-cover group",value:"37 lb-ft",note:"50 N·m"},{label:"Cable retaining clip",value:"80 lb-in",note:"9 N·m"}],source:chevy53OilPan2005,diagram:"main"},
  {slug:"dodge/5-7-hemi/exhaust-manifold-torque",keyword:"dodge 5.7 hemi exhaust manifold torque spec",make:"Dodge",model:"2006 Ram 2500 5.7L HEMI",title:"2006 Dodge Ram 5.7 HEMI Exhaust Manifold Torque",answer:"For the covered 2006 Ram 2500 5.7L HEMI, tighten the exhaust-manifold bolts in the factory sequence to 18 lb-ft (25 N·m). Tighten the heat-shield nuts separately to 11 lb-ft (15 N·m).",scope:"The values apply to the documented 2006 Ram 2500 factory manifolds and hardware. Other HEMI years, car applications, revised bolts and shields, aftermarket headers and repaired cylinder-head threads require their exact instructions.",detail:"Install a new gasket and follow the illustrated sequence rather than merely sweeping left to right. Mopar's procedure limits gasket-surface distortion to 0.008 inch per foot; check flatness and cracks and repair broken rear bolts instead of increasing torque on the remaining fasteners.",values:[{label:"Manifold bolts",value:"18 lb-ft",note:"25 N·m; illustrated sequence"},{label:"Heat-shield nuts",value:"11 lb-ft",note:"15 N·m; separate hardware"},{label:"Maximum flange variation",value:"0.008 in per ft",note:"0.2 mm per 300 mm"},{label:"Exhaust-pipe flange",value:"Separate specification",note:"Do not reuse manifold-bolt value"}],source:hemi57Exhaust2006},
  {slug:"dodge/5-7-hemi/flywheel-flexplate-torque",keyword:"dodge 5.7 hemi flywheel torque spec",make:"Dodge",model:"2005 Ram 1500 5.7L HEMI",title:"2005 Dodge Ram 5.7 HEMI Flywheel and Flexplate Torque",answer:"For the covered 2005 Ram 1500 5.7L HEMI, automatic-transmission flexplate retaining bolts use 70 lb-ft (95 N·m). The manual-transmission flywheel-to-crankshaft bolts use a separate 55 lb-ft (75 N·m) specification.",scope:"These two rows apply to the documented 2005 Ram 1500 production joints after transmission type is confirmed. Heavy-duty dual-mass flywheels, later eight-speed applications, replacement plates and aftermarket bolts require their corresponding procedure.",detail:"Do not average or interchange the automatic and manual values. Verify plate orientation, crank flange cleanliness, ring-gear condition and the exact bolt length, then hand-start all fasteners and tighten evenly in a crossing sequence so the plate seats flat.",values:[{label:"Automatic flexplate retaining bolts",value:"70 lb-ft",note:"95 N·m"},{label:"Manual flywheel to crankshaft",value:"55 lb-ft",note:"75 N·m"},{label:"Torque-converter fasteners",value:"Separate joint",note:"Use transmission-specific procedure"},{label:"Dual-mass flywheel",value:"Different hardware",note:"Do not transfer light-duty chart"}],source:hemi57Flywheel2005,diagram:"main"},
  {slug:"dodge/5-7-hemi/harmonic-balancer-torque",keyword:"dodge 5.7 hemi harmonic balancer torque spec",make:"Dodge",model:"2005 Ram 1500 5.7L HEMI",title:"2005 Dodge Ram 5.7 HEMI Harmonic Balancer Torque",answer:"For the covered 2005 Ram 1500 5.7L HEMI, tighten the production crankshaft-damper bolt to 129 lb-ft (176 N·m) after pressing the damper fully into position with the specified installer.",scope:"The value is anchored to the documented 2005 5.7L truck crankshaft, damper and bolt. Later HEMI generations, aftermarket dampers, supercharger hubs and performance bolt kits require their exact lubricant and clamp procedure.",detail:"Thoroughly clean the damper bore and crankshaft nose, coat the installation tool as directed and press the damper on with the dedicated tool. Do not hammer the damper or use the retaining bolt to drag it from the end of the crank; the 129-lb-ft fastener is applied only after correct seating.",values:[{label:"Crankshaft damper bolt",value:"129 lb-ft",note:"176 N·m; covered production hardware"},{label:"Damper installation",value:"Special installer 8512-A",note:"Press into position before final bolt torque"},{label:"Bore and crank nose",value:"Clean and inspected",note:"Contamination can damage the joint"},{label:"Aftermarket hub or bolt",value:"Manufacturer procedure",note:"Lubricant and torque may differ"}],source:hemi57Balancer2005,diagram:"timing"},
];
const researchedTorqueEditorial:Record<string,{sections:SpecRecord["sections"];faqs:SpecRecord["faqs"]}>={
  "ford/302/exhaust-manifold-torque":{sections:[
    {heading:"Separate the two exhaust fastener joints",paragraphs:["Ford lists 18–24 lb-ft for the cast exhaust manifold where it clamps to the cylinder head. The downstream manifold-to-catalytic-converter nuts are a different joint and use 25–34 lb-ft; swapping the two rows can overload the head threads or leave the pipe flange loose.","Label removed hardware and preserve brackets, shields and Thermactor connections. Emissions plumbing can change access and bolt locations even when the basic 5.0L casting is familiar."]},
    {heading:"Preventing a repeat exhaust leak",paragraphs:["Check the cast manifold with a straightedge and inspect the head sealing face, fasteners and bolt holes. A warped flange or broken fastener will not seal reliably just because the remaining bolts reach 24 lb-ft.","Start every fastener by hand and tighten progressively from the center area toward the ends using the service order. Header bolts, aluminum heads and aftermarket gaskets use their manufacturers' torque and recheck directions."]},
  ],faqs:[{q:"What is the 1996 Ford 302 exhaust-manifold torque?",a:"The covered F-150 specification is 18–24 lb-ft (25–32 N·m) for the manifold-to-cylinder-head fasteners."},{q:"What torque applies at the catalytic-converter flange?",a:"The covered service information lists the separate exhaust-manifold-to-converter nuts at 25–34 lb-ft."},{q:"Can extra torque seal a warped Ford 302 manifold?",a:"No. Check flange flatness, gasket requirements, broken hardware and thread condition instead of exceeding the specification."},{q:"Do tube headers use the factory cast-manifold range?",a:"Only if the header, gasket and cylinder-head instructions explicitly specify it; otherwise follow the component maker."}]},
  "ford/302/oil-pan-bolt-torque":{sections:[
    {heading:"Why the 9–11-lb-ft range is intentionally low",paragraphs:["The covered stamped pan uses 9–11 lb-ft across its attaching bolts. The flange only needs enough clamp to compress the gasket uniformly; higher torque can pull the sheet metal into dimples around each bolt hole.","Place a straightedge across the rail before assembly and flatten raised holes carefully. A distorted rail creates gaps between fasteners that extra torque makes worse."]},
    {heading:"Sealant placement and tightening method",paragraphs:["Clean the pan, block rails, front-cover corners and rear-main-cap joint. Apply only the gasket or service procedure's specified dabs at the transition points; coating the complete gasket with excess RTV can let it slide or squeeze material into the crankcase.","Start all bolts by hand and use several alternating passes around the pan before the 9–11-lb-ft finish. A cast pan, aftermarket one-piece gasket or main-cap stud girdle may use different fasteners and instructions."]},
  ],faqs:[{q:"What is the 1996 Ford 302 oil-pan bolt torque?",a:"Tighten the covered stamped-pan bolts evenly to 9–11 lb-ft (12–15 N·m)."},{q:"Why does a Ford 302 oil pan leak after tightening?",a:"Common causes include dimpled rails, misplaced corner seals, excessive RTV, a shifted gasket or damage at the front-cover and rear-cap transitions."},{q:"Can I tighten the pan bolts harder to stop seepage?",a:"No. Overtightening distorts the stamped flange and can split or displace the gasket."},{q:"Does an aftermarket cast-aluminum pan use 9–11 lb-ft?",a:"Not automatically. Follow the pan and gasket manufacturers' fastener-size and tightening instructions."}]},
  "ford/302/flywheel-bolt-torque":{sections:[
    {heading:"The covered production flywheel joint",paragraphs:["Ford lists 75–85 lb-ft for the 1996 5.0L flywheel-to-crankshaft bolts. Apply that range only after identifying the manual flywheel, production-style crank flange and matching bolt set.","Automatic flexplates, aftermarket steel or aluminum flywheels and performance bolts may use different thread treatment and torque. Their instructions replace the factory production row."]},
    {heading:"Balance, seating and runout checks",paragraphs:["The late 5.0L normally requires the matching 50-ounce-inch imbalance. A flywheel with the wrong balance can produce severe vibration even if every bolt is tightened correctly.","Clean both mating faces, verify dowels or indexing features, hand-start the correct bolts and tighten in progressive crisscross passes. Measure runout when the service or flywheel instructions require it; torque cannot pull dirt or a burr flat safely."]},
  ],faqs:[{q:"What is the 1996 Ford 302 flywheel-bolt torque?",a:"The covered F-150 service specification is 75–85 lb-ft (102–115 N·m)."},{q:"Does this value apply to an automatic flexplate?",a:"Do not assume so. Use the transmission, flexplate and bolt procedure for the exact automatic application."},{q:"What imbalance does a late Ford 5.0L flywheel commonly use?",a:"The covered late-production family commonly uses a 50-ounce-inch imbalance, but confirm the crank and flywheel part numbers."},{q:"Do aftermarket flywheel bolts use 75–85 lb-ft?",a:"Use the bolt maker's specified lubricant and torque because friction and bolt design can change the required value."}]},
  "ford/302/harmonic-balancer-bolt-torque":{sections:[
    {heading:"The 1996 crankshaft-damper specification",paragraphs:["Ford's covered truck specification assigns 70–90 lb-ft to the damper retaining bolt. The range assumes the production crank snout, damper, washer and bolt are compatible and undamaged.","A replacement performance damper or bolt can publish a different procedure. Confirm part numbers instead of choosing the top of the factory range for every Windsor build."]},
    {heading:"Seat the damper before applying final torque",paragraphs:["Lubricate and install the hub only as the damper maker or service procedure directs, align the keyway, and use a threaded installer that presses against the crankshaft correctly. Hammering can damage the thrust bearing, hub and elastomer.","The retaining bolt is for clamping the seated damper, not for dragging a tight hub from the end of the crank snout. If installation force becomes abnormal, stop and inspect bore size, burrs, key alignment and installer setup."]},
  ],faqs:[{q:"What is the 1996 Ford 302 harmonic-balancer bolt torque?",a:"The covered F-150 specification is 70–90 lb-ft (95–122 N·m)."},{q:"Can the crank bolt be used to pull the damper onto the crankshaft?",a:"No. Seat the damper with a dedicated installer before applying the retaining-bolt torque."},{q:"Should a Ford 302 damper be hammered into place?",a:"No. Hammering can damage the hub, elastomer, crankshaft and thrust bearing."},{q:"Does an aftermarket balancer use 70–90 lb-ft?",a:"Only when its manufacturer confirms the factory bolt, washer, thread treatment and range for that exact damper."}]},
  "chevrolet/5-3/exhaust-manifold-torque":{sections:[
    {heading:"Use the center-out two-pass sequence",paragraphs:["The 2005 Gen III service procedure does not treat 18 lb-ft as a one-step target. Bring the bolts to 11 lb-ft first, beginning at the center pair and alternating toward the ends, then repeat that path at 18 lb-ft. The staged pattern spreads clamp load across a long casting without forcing one end flat.","The pipe-flange nuts are downstream fasteners and use 37 lb-ft. Heat-shield screws use only 80 lb-in. Keeping those rows separate prevents the two most likely unit and joint errors on this repair."]},
    {heading:"Fix the sealing problem before tightening",paragraphs:["A snapped rear bolt, eroded gasket or bowed manifold flange can leave a cold-start tick even when the surviving bolts click at specification. Remove broken hardware correctly, check the head threads and test the flange with a straightedge; replace or machine a distorted casting as appropriate.","Use a new gasket and the specified threadlocker placement, leaving the first three threads free. Header kits may specify different gaskets, bolts, lubricant and hot-cycle rechecks, so their instructions supersede this cast-manifold chart."]},
  ],faqs:[{q:"What is the 2005 Chevy 5.3 exhaust-manifold torque?",a:"Tighten the factory manifold bolts center-out to 11 lb-ft, then repeat the sequence to 18 lb-ft."},{q:"What torque applies to the exhaust-pipe nuts?",a:"The separate manifold-to-pipe nuts are tightened to 37 lb-ft (50 N·m) in the covered procedure."},{q:"Should threadlocker cover every exhaust-manifold bolt thread?",a:"No. The procedure calls for a 5-mm band of the specified product while leaving the first three threads bare."},{q:"Will tightening the remaining bolts stop a rear manifold leak?",a:"Not reliably. Inspect for a broken rear fastener, warped casting, failed gasket and damaged head threads before reassembly."}]},
  "chevrolet/5-3/flywheel-flexplate-torque":{sections:[
    {heading:"Do not mix crank bolts with converter bolts",paragraphs:["The flywheel or flexplate fasteners that clamp directly to the crankshaft use three passes: 15, 37 and 74 lb-ft. The torque converter attaches to the plate through a different set of fasteners at 46 lb-ft. Both joints are nearby during transmission work, but they carry different loads and cannot share one wrench setting.","Confirm plate orientation and bolt length before tightening. A wrong plate, spacer or manual-conversion combination can contact the block or converter even when the bolt torque is correct."]},
    {heading:"Draw the plate down evenly",paragraphs:["Clean away rust, burrs and old compound from the crank flange and plate. Apply the specified threadlocker, start every bolt by hand and follow a crossing sequence through all three stages; this progressively seats the unpinned plate without cocking it against the flange.","Inspect the ring gear and measure runout when the applicable service information requires it. Aftermarket flywheel and fastener makers may publish a different lubricated torque, so use their instructions as a matched system rather than combining them with the factory value."]},
  ],faqs:[{q:"What is the 2005 Chevy 5.3 flexplate or flywheel bolt torque?",a:"The covered crank bolts use 15 lb-ft, then 37 lb-ft, and a final 74 lb-ft in sequence."},{q:"What is the 5.3 torque-converter bolt torque?",a:"For the covered 2005 joint, the converter-to-flexplate bolts use 46 lb-ft (63 N·m), not the crank-bolt stages."},{q:"Does the factory flywheel use a locating pin?",a:"The cited installation procedure says it does not; the staged sequence draws it evenly against the crank flange."},{q:"Can an aftermarket bolt kit use the factory 74-lb-ft finish?",a:"Only when its manufacturer specifies that value with the exact lubricant or threadlocker supplied for the kit."}]},
  "chevrolet/5-3/harmonic-balancer-torque":{sections:[
    {heading:"The old and new bolts have different jobs",paragraphs:["The used bolt is a temporary seating tool. After the installer places the balancer on the crank, tighten that used bolt to 240 lb-ft, remove it and check the recess measurement. It does not remain in the engine.","Final retention requires a new bolt at 37 lb-ft plus 140 degrees. Presenting only the 240-lb-ft number can leave a fatigued bolt installed or lead someone to apply the seating load to the new torque-to-yield fastener incorrectly."]},
    {heading:"Check seating before the angle turn",paragraphs:["The crank nose should sit 0.094–0.176 inch inside the balancer bore after seating. If it does not, stop and inspect the hub bore, crank snout, installation-tool setup and alignment rather than relying on the new bolt to finish pulling the hub into place.","Use a proper angle gauge for the 140-degree turn and hold the crankshaft with the approved method. An aftermarket damper or reusable performance bolt is a different engineered joint and follows its maker's lubricant, washer and torque instructions."]},
  ],faqs:[{q:"What is the final Chevy 5.3 harmonic-balancer bolt torque?",a:"For the covered 2005 Gen III engine, install a new bolt at 37 lb-ft and then turn it another 140 degrees."},{q:"Why does the procedure also list 240 lb-ft?",a:"That value is only for seating the balancer with the old bolt, which is removed before the new final bolt is installed."},{q:"How far should the crank nose be recessed in the balancer?",a:"The covered specification is 0.094–0.176 inch (2.4–4.48 mm) after the seating step."},{q:"Can I reuse the old bolt as the final balancer fastener?",a:"No. In this procedure the old bolt performs the temporary seating step and a new bolt provides the final clamp."}]},
  "chevrolet/5-3/oil-pan-bolt-torque":{sections:[
    {heading:"Three bolt groups, three settings",paragraphs:["The main pan and pan-to-front-cover fasteners use 18 lb-ft, but the small rear-cover fasteners use 106 lb-in. The bellhousing and converter-cover attachment group uses 37 lb-ft. Sort the bolts by location before starting so an inch-pound rear fastener never receives a structural bolt's setting.","Bring the pan into position with all fasteners loose, snug it evenly and confirm the rear face alignment before final torque. Tightening one end first can shift the pan at the front cover or transmission interface."]},
    {heading:"Gasket, sealant and leak-control details",paragraphs:["Fit the new gasket so its oil-gallery openings remain aligned. The procedure calls for short, 5-mm beads of the specified sealant at the block-to-cover joint tabs, not a heavy bead around the whole perimeter; excess sealant can squeeze inward while too little at the joints can create a repeat leak.","A seep after installation may come from the rear cover, front cover, oil-level sensor, drain plug or a distorted pan rather than the rail itself. Clean the area and trace the highest wet point before retightening bolts that are already at specification."]},
  ],faqs:[{q:"What is the 2005 Chevy 5.3 oil-pan bolt torque?",a:"The main pan and pan-to-front-cover fasteners use 18 lb-ft (25 N·m) in the covered application."},{q:"What torque applies to the rear-cover oil-pan bolts?",a:"Those smaller fasteners use 106 lb-in (12 N·m); the unit is inch-pounds, not foot-pounds."},{q:"What torque applies to the bellhousing-side fasteners?",a:"The covered bellhousing and converter-cover bolt or stud group uses 37 lb-ft (50 N·m)."},{q:"Should RTV cover the entire Chevy 5.3 oil-pan gasket?",a:"No. Use the new gasket and place the specified short sealant beads only at the documented block-to-cover joint tabs."}]},
  "chevrolet/350/exhaust-manifold-torque":{sections:[{heading:"Why the center pair has a higher value",paragraphs:["The 1996 Vortec truck chart assigns 26 lb-ft to the two center bolts and 20 lb-ft everywhere else. Mark those center positions before assembly; applying 26 lb-ft to every fastener erases a distinction Chevrolet made for the factory casting.","Start all bolts by hand and bring the manifold down progressively from the center toward both ends. A staged center-out approach seats the long flange without using an outer fastener to lever the casting into place."]},{heading:"Diagnose a tick before reaching for the wrench",paragraphs:["Cold-start ticking commonly points to a cracked casting, failed gasket, loose or broken bolt, eroded port face or warped flange. Check flatness and thread condition because a wrench reading cannot prove the joint is geometrically sound.","This chart is specific to the 1996 truck's factory cast manifold and Vortec iron head. Tube headers, aluminum heads and different gasket/bolt kits follow their makers' torque and heat-cycle instructions."]}],faqs:[{q:"What is the 1996 Chevy 350 exhaust-manifold torque?",a:"The two center bolts use 26 lb-ft, while all remaining manifold bolts use 20 lb-ft."},{q:"Can every Chevy 350 manifold bolt be tightened to 26 lb-ft?",a:"No. The covered specification deliberately assigns the higher value only to the center pair."},{q:"Will more torque repair an exhaust tick?",a:"No. Inspect for cracks, flange distortion, gasket failure, broken hardware and damaged cylinder-head threads."},{q:"Do tube headers use the 20/26-lb-ft chart?",a:"Not automatically. Follow the header, gasket and cylinder-head instructions for that exact combination."}]},
  "dodge/5-7-hemi/exhaust-manifold-torque":{sections:[{heading:"Use the illustrated 18-lb-ft sequence",paragraphs:["Install every manifold bolt loosely with a new gasket, then follow Mopar's numbered sequence to 18 lb-ft. The heat shield is a separate layer whose nuts use 11 lb-ft; labeling hardware prevents the shield setting from being confused with the manifold joint.","The exhaust-pipe flange and engine-mount hardware disturbed for access have their own specifications. A complete repair worksheet should keep each nearby joint on a separate row."]},{heading:"Broken bolts and flange flatness",paragraphs:["Mopar limits gasket-surface variation to 0.008 inch per foot. Check the removed manifold with a straightedge and inspect for cracks; clamping a warped flange harder can break another bolt without closing the leak uniformly.","Extract broken rear bolts without damaging the aluminum head, restore questionable threads correctly and use the exact revised hardware when a model-specific kit applies. Headers and later HEMI revisions do not inherit this 2006 truck chart automatically."]}],faqs:[{q:"What is the 2006 Dodge Ram 5.7 HEMI exhaust-manifold torque?",a:"Tighten the factory manifold bolts in the illustrated sequence to 18 lb-ft (25 N·m)."},{q:"What is the heat-shield nut torque?",a:"The covered heat-shield nuts use 11 lb-ft (15 N·m), separate from the manifold bolts."},{q:"How flat must the HEMI manifold flange be?",a:"The cited procedure limits variation to 0.008 inch per foot (0.2 mm per 300 mm)."},{q:"Can extra torque compensate for a broken rear bolt?",a:"No. Remove the broken fastener, inspect the threads and flange, and restore the complete joint."}]},
  "dodge/5-7-hemi/flywheel-flexplate-torque":{sections:[{heading:"Transmission type changes the answer",paragraphs:["The automatic flexplate retaining bolts use 70 lb-ft, while the manual flywheel-to-crankshaft bolts use 55 lb-ft in the covered 2005 Ram 1500 data. Select the row by the actual transmission and rotating parts, not by the shared 5.7L engine badge.","Torque-converter bolts attach to the flexplate but are not flexplate retaining bolts. Keep that downstream joint on its own transmission-specific specification."]},{heading:"Plate seating, balance and bolt checks",paragraphs:["Clean the crank flange and plate mating face, inspect the ring gear and verify orientation and balance before starting every correct-length bolt by hand. Tighten progressively in a crossing pattern so rust, a burr or a cocked plate cannot hide behind a final wrench reading.","Heavy-duty dual-mass assemblies and aftermarket flywheels can add an adapter, different bolts or another clamp specification. Follow the matched component instructions instead of combining one part's torque with another part's lubricant."]}],faqs:[{q:"What is the 2005 Ram 5.7 HEMI flexplate bolt torque?",a:"The automatic-transmission flexplate retaining bolts use 70 lb-ft (95 N·m)."},{q:"What is the manual flywheel bolt torque?",a:"The covered flywheel-to-crankshaft bolts use 55 lb-ft (75 N·m)."},{q:"Are torque-converter bolts tightened to 70 lb-ft?",a:"Do not assume so; they form a separate joint governed by the exact transmission procedure."},{q:"Does a dual-mass flywheel use this light-duty chart?",a:"Not automatically. Its adapter and flywheel fasteners can have separate specifications."}]},
  "dodge/5-7-hemi/harmonic-balancer-torque":{sections:[{heading:"Seat the damper before applying 129 lb-ft",paragraphs:["Mopar's procedure first slides the damper onto the crank and then presses it home with installer 8512-A. Only after the hub is correctly seated is the retaining bolt tightened to 129 lb-ft.","Using the bolt as a draw tool loads too few crank threads while the interference fit is highest. Hammering can damage the hub, elastomer, crankshaft and thrust surfaces; neither shortcut is part of the service method."]},{heading:"Tool setup and surface preparation",paragraphs:["Clean the crank nose and damper bore thoroughly. The installer is assembled in a prescribed order with its hardened bearing face and washer oriented correctly, and its threaded rod receives the specified anti-seize so the tool turns without galling.","Stop if installation force becomes abnormal and inspect for burrs, misalignment or an incorrect damper. Performance bolts and supercharger hubs use their manufacturers' washer, lubricant and torque rather than the production 129-lb-ft row."]}],faqs:[{q:"What is the 2005 Ram 5.7 HEMI harmonic-balancer bolt torque?",a:"Tighten the production crankshaft-damper bolt to 129 lb-ft (176 N·m) after seating the damper."},{q:"Can the damper bolt pull the balancer onto the crank?",a:"No. The covered procedure uses dedicated installer 8512-A before the retaining bolt is tightened."},{q:"Should the HEMI damper be hammered into place?",a:"No. Press it on with the specified installer to avoid damage to the damper and crankshaft."},{q:"Do aftermarket damper bolts use 129 lb-ft?",a:"Only if the bolt and damper manufacturers specify that value with their exact washer and lubricant."}]},
};
function torquePage(j:TorqueJob):SpecRecord{const record:SpecRecord={slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Torque Specs",title:j.title,
  metaDescription:`${j.title} with fastener-group distinctions, installation cautions, application limits and official source lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,values:j.values,sources:j.sources??[j.source],reviewed,featureImage:engineImage,featureOverlay:true,
  diagram:{type:j.diagram??"intake",title:`Interactive ${j.model} fastener map`,caption:"Orientation aid only. Match every position and stage to the exact service diagram.",points:["1","5","3","7","8","4","6","2"]},intro:[j.answer,j.scope],steps:["Identify the exact engine, component, fastener size and hardware instructions.","Clean and inspect threads and mating faces; apply only the specified lubricant or sealant.","Tighten in gradual balanced passes and verify any angle, cure-time or recheck instruction."],sections:[{heading:`Application boundaries for ${j.model}`,paragraphs:[j.scope,j.detail]}],faqs:dieselServiceFaqs[j.slug]??[{q:`What is the ${j.keyword}?`,a:j.answer},{q:"Does aftermarket hardware use the stock torque?",a:"Not automatically. Use the component or fastener maker's instructions for its exact hardware and lubricant."},{q:"Can extra torque stop a leak?",a:"No. Diagnose flatness, cracks, gasket alignment, fastener condition and thread damage instead of overtightening."}]};const editorial=researchedTorqueEditorial[j.slug];if(editorial){record.sections.unshift(...editorial.sections);record.faqs=editorial.faqs;record.intro=[record.answer,record.scope,record.detail];}return record;}

type OilJob={slug:string;keyword:string;make:string;model:string;title:string;answer:string;scope:string;detail:string;capacity:string;liters:string;source:Source};
const oilJobs:OilJob[]=[
  {slug:"ford/f-150/2015/3-5-ecoboost/oil-capacity",keyword:"2015 ford f150 oil capacity 3.5 ecoboost",make:"Ford",model:"2015 F-150 3.5L EcoBoost",title:"2015 Ford F-150 3.5 EcoBoost Oil Capacity",answer:"Ford specifies 6.0 US qt (5.7 L) for a 2015 F-150 3.5L EcoBoost oil-and-filter change.",scope:"Applies specifically to the first-generation 3.5L EcoBoost in the 2015 F-150. Do not transfer the capacity from a later second-generation 3.5L EcoBoost or another Ford model.",detail:"The same manual calls for SAE 5W-30 meeting Ford WSS-M2C946-A. Add slightly less than the published capacity first, run the engine to fill the filter, shut it down, allow drain-back on level ground and finish by the dipstick without exceeding MAX.",capacity:"6.0 US qt",liters:"5.7 L; with filter",source:ford2015F150},
  {slug:"ford/f-150/2016/2-7-ecoboost/oil-capacity",keyword:"2016 ford f150 oil capacity 2.7 ecoboost",make:"Ford",model:"2016 F-150 2.7L EcoBoost",title:"2016 Ford F-150 2.7 EcoBoost Oil Capacity",answer:"Ford specifies 6.0 US qt (5.7 L) with the filter for the 2016 F-150 2.7L EcoBoost.",scope:"Applies to the 2016 F-150 equipped with the 2.7L EcoBoost. Similar displacement does not make a later-generation engine or another vehicle application interchangeable.",detail:"Use SAE 5W-30 oil carrying the Ford approval shown in the model-year manual. Reinstall the correct filter and drain plug, refill below the nominal total, run briefly while checking for leaks, wait for drain-back and use the dipstick as the final authority.",capacity:"6.0 US qt",liters:"5.7 L; with filter",source:ford2016F150},
  {slug:"ford/f-150/2017/5-0/oil-capacity",keyword:"2017 ford f150 oil capacity 5.0",make:"Ford",model:"2017 F-150 5.0L V8",title:"2017 Ford F-150 5.0 Oil Capacity",answer:"Ford specifies 7.7 US qt (7.3 L) with the oil filter for the 2017 F-150 5.0L V8.",scope:"Applies to the 2017 F-150 5.0L Coyote V8. The revised 2018 5.0L has a different published capacity, so model year must be part of the lookup.",detail:"Use SAE 5W-20 meeting the Ford specification in the 2017 manual. Do not round this page to an 8-qt bottle count or substitute the later 8.8-qt figure; refill progressively and verify the final level on the dipstick after the filter is filled and the oil has drained back.",capacity:"7.7 US qt",liters:"7.3 L; with filter",source:ford2017F150},
  {slug:"chevrolet/silverado-1500/2018/5-3/oil-capacity",keyword:"2018 chevy silverado 1500 5.3 oil capacity",make:"Chevrolet",model:"2018 Silverado 1500 5.3L",title:"2018 Chevy Silverado 1500 5.3 Oil Capacity",answer:"GM lists 8.0 US qt (7.6 L) with the oil filter for the 2018 Silverado 1500 5.3L V8.",scope:"Applies to the light-duty 2018 Silverado 1500 with the 5.3L gasoline V8. It does not cover Silverado HD engines, Duramax applications or a different displacement.",detail:"The manual calls for the specified dexos-approved oil and viscosity for the engine. Add less than the full eight quarts initially, run the engine while checking for leaks, allow drain-back on level ground and finish at the dipstick rather than assuming every drained engine accepts the nominal total immediately.",capacity:"8.0 US qt",liters:"7.6 L; with filter",source:chevy2018Silverado},
  {slug:"chevrolet/silverado-1500/2019/6-2/oil-capacity",keyword:"2019 chevy silverado 1500 6.2 oil capacity",make:"Chevrolet",model:"2019 Silverado 1500 6.2L",title:"2019 Chevy Silverado 1500 6.2 Oil Capacity",answer:"The new-body 2019 Silverado 1500 6.2L L87 takes 8.0 US qt (7.6 L) with the oil filter.",scope:"Applies to the 2019 light-duty Silverado 1500 equipped with the 6.2L L87 V8. The 2019 model year also includes carryover/LD trucks, so identify the VIN, body generation and engine before using surrounding service data.",detail:"GM groups the 5.3L and 6.2L 1500-series V8 oil capacity at 8.0 qt in the cited manual, but oil specification, filter and other service parts remain engine-code specific. Refill progressively and verify the final level after drain-back.",capacity:"8.0 US qt",liters:"7.6 L; with filter",source:chevy2019Silverado},
  {slug:"ram/1500/2020/5-7-hemi/oil-capacity",keyword:"2020 ram 1500 5.7 hemi oil capacity",make:"Ram",model:"2020 1500 5.7L HEMI",title:"2020 Ram 1500 5.7 HEMI Oil Capacity",answer:"The 2020 Ram 1500 DT with either 5.7L HEMI configuration takes 7.0 US qt (6.6 L) with a new oil filter.",scope:"Applies to the fifth-generation 2020 Ram 1500 DT 5.7L HEMI, including eTorque where equipped. The concurrently sold Ram 1500 Classic uses the DS-platform manual and should be identified separately.",detail:"Ram specifies API-certified SAE 5W-20 meeting FCA Material Standard MS-6395. Refill below the seven-quart reference first, start the engine and check for leaks, shut it down on level ground, allow the oil to drain back and use the dipstick for the final top-off. The manual also says the filter should be replaced at every oil change.",capacity:"7.0 US qt",liters:"6.6 L; with filter",source:ram2020_1500},
  {slug:"toyota/tacoma/2021/3-5/oil-capacity",keyword:"2021 toyota tacoma 3.5 oil capacity",make:"Toyota",model:"2021 Tacoma 3.5L V6",title:"2021 Toyota Tacoma 3.5 Oil Capacity",answer:"Toyota lists 6.2 US qt (5.9 L) with a new filter for the 2021 Tacoma 3.5L 2GR-FKS V6.",scope:"Applies to U.S.-market 2021 Tacoma models equipped with the 3.5L 2GR-FKS. It does not apply to the 2.7L four-cylinder or to the redesigned turbocharged Tacoma introduced later.",detail:"Treat 6.2 qt as a drain-and-refill reference, not a command to pour in the full amount at once. Install the correct filter and drain-plug gasket, add slightly less than the reference, run the engine, inspect for leaks, wait more than five minutes on level ground and finish at the dipstick. Use the oil grade and viscosity stated in the same model-year manual.",capacity:"6.2 US qt",liters:"5.9 L; with filter",source:toyota2021Tacoma},
  {slug:"toyota/camry/2018/2-5/oil-capacity",keyword:"2018 toyota camry 2.5 oil capacity",make:"Toyota",model:"2018 Camry 2.5L",title:"2018 Toyota Camry 2.5 Oil Capacity",answer:"Toyota lists 4.8 US qt (4.5 L) with a new filter for the gasoline 2018 Camry 2.5L A25A-FKS.",scope:"Applies to the conventional gasoline 2018 Camry 2.5L A25A-FKS. The Camry Hybrid uses the A25A-FXS and a separate owner-manual section, while the available 3.5L V6 has a different capacity.",detail:"Toyota describes the figure as a drain-and-refill reference. Add below 4.8 qt initially, run the engine long enough to fill the filter, inspect the drain plug and filter, switch off, wait more than five minutes on level ground and bring the dipstick level into range. The gasoline A25A-FKS page specifies SAE 0W-16; if 0W-20 is used only because 0W-16 is unavailable, Toyota directs replacement with 0W-16 at the next change.",capacity:"4.8 US qt",liters:"4.5 L; with filter",source:toyota2018Camry},
  {slug:"toyota/rav4/2019/2-5/oil-capacity",keyword:"2019 toyota rav4 2.5 oil capacity",make:"Toyota",model:"2019 RAV4 2.5L",title:"2019 Toyota RAV4 2.5 Oil Capacity",answer:"Toyota lists 4.8 US qt (4.5 L) with a new filter for the gasoline 2019 RAV4 2.5L A25A-FKS.",scope:"Applies to the conventional gasoline 2019 RAV4 with the A25A-FKS engine. The RAV4 Hybrid uses the A25A-FXS and its own manual, so engine and powertrain identity should be confirmed even when the nominal refill amount appears similar.",detail:"The published capacity is a reference for a drain and refill. Start below the full 4.8 qt, run the engine while checking for leakage, shut it off on level ground, wait more than five minutes and finish by the dipstick. Toyota specifies SAE 0W-16 for this application; temporary 0W-20 use carries a return-to-0W-16 instruction at the next oil change.",capacity:"4.8 US qt",liters:"4.5 L; with filter",source:toyota2019Rav4},
  {slug:"honda/civic/2020/1-5-turbo/oil-capacity",keyword:"2020 honda civic 1.5t oil capacity",make:"Honda",model:"2020 Civic 1.5L Turbo",title:"2020 Honda Civic 1.5T Oil Capacity",answer:"Honda lists 3.7 US qt (3.5 L) including a new filter for the 2020 Civic 1.5L turbo.",scope:"Applies to U.S.-market 2020 Civic 1.5L turbo models after confirming body style and engine. It does not apply to the naturally aspirated 2.0L or the 2.0L turbo Type R.",detail:"Honda recommends 0W-20 and distinguishes 3.4 qt for an oil-only drain from 3.7 qt when the filter is changed. Install a new drain-bolt washer, refill below the reference first, run the engine while checking for leakage, shut it off on level ground, wait about three minutes and finish at the dipstick rather than by bottle count.",capacity:"3.7 US qt",liters:"3.5 L; including filter",source:honda2020Civic},
  {slug:"honda/cr-v/2017/1-5-turbo/oil-capacity",keyword:"2017 honda crv 1.5t oil capacity",make:"Honda",model:"2017 CR-V 1.5L Turbo",title:"2017 Honda CR-V 1.5T Oil Capacity",answer:"Honda lists 3.7 US qt (3.5 L) including a new filter for the 2017 CR-V 1.5L turbo.",scope:"Applies to the 2017 CR-V equipped with the 1.5L turbo. The same model year also offered a 2.4L naturally aspirated engine in some trims, and its refill figure must not be substituted.",detail:"Use 0W-20 engine oil carrying the API certification specified by Honda. Replace the drain-bolt sealing washer, add slightly less than 3.7 qt, start the engine and inspect the filter and drain bolt, then stop on level ground and wait about three minutes before the final dipstick check. Reset the Maintenance Minder only after the service is complete.",capacity:"3.7 US qt",liters:"3.5 L; including filter",source:honda2017Crv},
  {slug:"jeep/wrangler/2018/3-6/oil-capacity",keyword:"2018 jeep wrangler 3.6 oil capacity",make:"Jeep",model:"2018 Wrangler 3.6L",title:"2018 Jeep Wrangler 3.6 Oil Capacity: JK vs. JL",answer:"For the 2018 overlap year, the all-new JL 3.6L takes 5.0 US qt (4.73 L), while the carryover JK 3.6L takes 6.0 US qt (about 5.7 L), both with a new filter.",scope:"Applies specifically to the 2018 Wrangler, when Jeep sold two generations. A JL has the newer body/interior and a JL VIN/platform designation; a Wrangler JK or JK Unlimited uses the earlier platform and its separate manual.",detail:"Do not average the two capacities. The JL manual specifies API-certified SAE 0W-20 meeting FCA MS-6395; the JK manual calls for the grade shown in its own oil section and filler cap. Add below the platform-specific total, run briefly, inspect for leaks, allow drain-back on level ground and finish by dipstick.",capacity:"JL: 5.0 qt; JK: 6.0 qt",liters:"JL: 4.73 L; JK: about 5.7 L",source:jeep2018Jl},
  {slug:"subaru/forester/2019/2-5/oil-capacity",keyword:"2019 subaru forester 2.5 oil capacity",make:"Subaru",model:"2019 Forester 2.5L",title:"2019 Subaru Forester 2.5 Oil Capacity",answer:"Subaru lists 4.4 US qt (4.2 L) for a 2019 Forester 2.5L oil-and-filter change.",scope:"Applies to the redesigned U.S.-market 2019 Forester with the direct-injected 2.5L FB25. Earlier Forester generations and turbocharged models use different capacities and service references.",detail:"Use the 0W-20 oil specification shown in the model-year manual and treat 4.4 qt as a refill reference. Confirm that the old filter gasket came off, install the correct filter and drain-plug sealing washer, fill below the reference, run the engine while checking for leaks, then wait on level ground and bring the dipstick level between the marks without overfilling.",capacity:"4.4 US qt",liters:"4.2 L; with filter",source:subaru2019Forester},
  {slug:"subaru/outback/2020/2-5/oil-capacity",keyword:"2020 subaru outback 2.5 oil capacity",make:"Subaru",model:"2020 Outback 2.5L",title:"2020 Subaru Outback 2.5 Oil Capacity",answer:"Subaru lists 4.4 US qt (about 4.2 L) during an oil-and-filter change for the 2020 Outback 2.5L.",scope:"Applies to the naturally aspirated 2.5L engine in the redesigned 2020 Outback. The available 2.4L turbo uses 4.8 US qt, so the engine label and trim must be confirmed before refill.",detail:"The Subaru guide calls for 0W-20 synthetic meeting its listed API/ILSAC requirements. Replace the filter and drain-plug sealing washer, fill below 4.4 qt first, run the engine while checking for leaks, then shut down on level ground and use the dipstick after drain-back. Subaru notes roughly one quart separates the low and full marks.",capacity:"4.4 US qt",liters:"About 4.2 L; with filter",source:subaru2020Outback},
  {slug:"nissan/altima/2017/2-5/oil-capacity",keyword:"2017 nissan altima 2.5 oil capacity",make:"Nissan",model:"2017 Altima 2.5L",title:"2017 Nissan Altima 2.5 Oil Capacity",answer:"Nissan lists 4-7/8 US qt (4.6 L) with a new filter for the 2017 Altima 2.5L QR25DE.",scope:"Applies to the 2017 Altima 2.5L four-cylinder. The 3.5L VQ35DE in the same manual uses 5-1/8 qt (4.8 L), so displacement must be confirmed before filling.",detail:"The manual recommends Genuine Nissan Motor Oil 0W-20 SN or an equivalent matching that grade and viscosity. Nissan labels the table values approximate: install the correct filter and drain-plug washer, add below 4-7/8 qt, run the engine, inspect for leaks, wait on level ground and determine the final amount from the dipstick.",capacity:"4-7/8 US qt",liters:"4.6 L; with filter",source:nissan2017Altima},
  {slug:"nissan/rogue/2018/2-5/oil-capacity",keyword:"2018 nissan rogue 2.5 oil capacity",make:"Nissan",model:"2018 Rogue 2.5L",title:"2018 Nissan Rogue 2.5 Oil Capacity",answer:"Nissan lists 4-7/8 US qt (4.6 L) with a new filter for the 2018 Rogue 2.5L QR25DE.",scope:"Applies to the full-size 2018 Rogue with the 2.5L QR25DE. It does not apply to the smaller Rogue Sport, which is a separate model with a different engine and manual.",detail:"The same table lists 4-1/2 qt (4.3 L) when the filter is not changed and recommends Nissan 0W-20 SN or equivalent. Because Nissan calls the capacities approximate, refill below the reference first, run the engine while checking the filter and drain plug, allow drain-back on level ground and finish by dipstick.",capacity:"4-7/8 US qt",liters:"4.6 L; with filter",source:nissan2018Rogue},
  {slug:"gmc/sierra-1500/2019/5-3/oil-capacity",keyword:"2019 gmc sierra 1500 5.3 oil capacity",make:"GMC",model:"2019 Sierra 1500 5.3L",title:"2019 GMC Sierra 1500 5.3 Oil Capacity",answer:"The new-body 2019 GMC Sierra 1500 5.3L V8 takes 8.0 US qt (7.6 L) with the oil filter.",scope:"Applies to 2019 Sierra 1500 5.3L gasoline applications after confirming L82 or L84 engine identity. The concurrently sold Sierra 1500 Limited/carryover is a separate manual and platform lookup.",detail:"Capacity is shared between the cited 5.3L variants, but engine code still controls oil specification and service parts. Add below the nominal total, run to fill the filter, inspect for leaks and verify on level ground after the prescribed drain-back interval.",capacity:"8.0 US qt",liters:"7.6 L; with filter",source:gmc2019Sierra},
  {slug:"ford/explorer/2020/2-3-ecoboost/oil-capacity",keyword:"2020 ford explorer 2.3 ecoboost oil capacity",make:"Ford",model:"2020 Explorer 2.3L EcoBoost",title:"2020 Ford Explorer 2.3 EcoBoost Oil Capacity",answer:"Ford lists 4.9 L, approximately 5.2 US qt, including the filter for the 2020 Explorer 2.3L EcoBoost.",scope:"Applies to the redesigned rear-wheel-drive-platform 2020 Explorer with the 2.3L EcoBoost. Do not substitute a Mustang, Ranger or earlier transverse Ford 2.3L capacity simply because the displacement matches.",detail:"The printed model-year manual specifies SAE 5W-30 meeting Ford WSS-M2C946-B1. Install the correct Motorcraft-equivalent filter and drain plug hardware, add slightly less than 4.9 L first, run the engine and inspect for leaks, then switch off on level ground and finish at the dipstick after the oil drains back.",capacity:"About 5.2 US qt",liters:"4.9 L; including filter",source:ford2020Explorer},
  {slug:"hyundai/elantra/2018/2-0/oil-capacity",keyword:"2018 hyundai elantra 2.0 oil capacity",make:"Hyundai",model:"2018 Elantra 2.0L",title:"2018 Hyundai Elantra 2.0 Oil Capacity",answer:"Hyundai lists 4.0 L (4.23 US qt) for a drain and refill on the 2018 Elantra Nu 2.0 MPI.",scope:"Applies to the regular 2018 Elantra sedan with the Nu 2.0 MPI after confirming market and engine. The Elantra Sport/Eco turbo engines and Elantra GT applications have separate specifications.",detail:"The manual groups the refill amount with the approved API/ILSAC oil classification and a separate viscosity chart; use both, not capacity alone. Replace the filter and drain-plug washer, add below 4.0 L first, run the engine and inspect for leaks, then wait on level ground and set the final level with the dipstick.",capacity:"4.23 US qt",liters:"4.0 L; drain and refill",source:hyundai2018Elantra},
  {slug:"kia/optima/2019/2-4/oil-capacity",keyword:"2019 kia optima 2.4 oil capacity",make:"Kia",model:"2019 Optima 2.4L",title:"2019 Kia Optima 2.4 Oil Capacity",answer:"Kia lists 4.8 L (5.07 US qt) for a drain and refill on the 2019 Optima 2.4L GDI.",scope:"Applies to U.S.-market 2019 Optima LX and S models with the 2.4L GDI. The 1.6L turbo, 2.0L turbo and hybrid powertrains use different refill data and should be identified separately.",detail:"Use the oil classification and viscosity chart from the same model-year manual; capacity by itself is not a complete oil specification. Refill below 4.8 L initially, run the engine while checking the new filter and drain plug, shut down on level ground, allow drain-back and finish at the dipstick without exceeding the full mark.",capacity:"5.07 US qt",liters:"4.8 L; drain and refill",source:kia2019Optima},
];
function oilPage(j:OilJob):SpecRecord{return oilGuide({slug:j.slug,keyword:j.keyword,make:j.make,model:j.model,category:"Fluid Capacities",title:j.title,
  metaDescription:`${j.title}: ${j.capacity} with filter, application boundaries, refill procedure, dipstick check and official manual lookup.`,answer:j.answer,scope:j.scope,detail:j.detail,
  values:[{label:"Oil and filter change",value:j.capacity,note:j.liters},{label:"Final level",value:"Verify after drain-back",note:"Level ground and correct procedure"}],sources:[j.source],identity:j.model,distinctions:[j.scope,j.detail],featureImage:oilImage,featureOverlay:true});}

export const dieselServiceSpecs:SpecRecord[]=[...firingJobs.map(firingPage),...headJobs.map(headPage),...torqueJobs.map(torquePage),...oilJobs.map(oilPage)];
